import java.nio.file.{Files, Path, StandardOpenOption}
import scala.util.Using

final class RecLog(path: Path) extends AutoCloseable {
  private val ch = Files.newByteChannel(path, StandardOpenOption.CREATE, StandardOpenOption.APPEND)
  def append(line: String): Unit = ch.write(java.nio.ByteBuffer.wrap(s"$line\n".getBytes))
  def close(): Unit = ch.close()
}

Using.resource(RecLog(path))(_.append("ready"))   // released even on failure

